-- Reviewed production SQL contract fixture only. No provider calls or public posts.
-- Existing dedicated QA owner and actual active session; all new rows rolled back.
-- Never replace authority helpers, disable triggers or print auth credentials.
BEGIN;
SET LOCAL lock_timeout='3s';SET LOCAL statement_timeout='45s';SET LOCAL idle_in_transaction_session_timeout='60s';
CREATE TEMP TABLE qa_publisher_results(label text PRIMARY KEY,passed boolean) ON COMMIT DROP;
GRANT INSERT,SELECT ON qa_publisher_results TO authenticated,service_role;
CREATE FUNCTION pg_temp.qa_publisher_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'qa_publisher_assertion_failed:%',label;END IF;INSERT INTO pg_temp.qa_publisher_results VALUES(label,true);END$$;
DO $qa$
DECLARE executor name:=current_user;
 ws constant uuid:='053a5656-b19b-48a4-8721-65c4674f647c';actor constant uuid:='21a04e78-e3b1-448e-8517-47aad25dd5da';account constant uuid:='2ba5b8e3-4fe9-4ec7-a3bf-7f616fcf07fd';
 listing constant uuid:='c1eb6d31-5454-4c5c-b52b-cd2610140001';foreign_listing constant uuid:='c1eb6d31-5454-4c5c-b52b-cd2610140002';other_ws constant uuid:='c1eb6d31-5454-4c5c-b52b-cd2610140003';channel_id constant bigint:=-9126101400001;ephemeral_session constant uuid:='c1eb6d31-5454-4c5c-b52b-cd2610140004';fixture_source constant text:='qa-publisher-aged-rollback-20261014';attempt jsonb;permit jsonb;review jsonb;source_record jsonb;due jsonb;snapshot jsonb;original_meta jsonb;sid uuid;category bigint;receipt jsonb;replay jsonb;post zoi.social_posts;denied boolean;
BEGIN
 IF EXISTS(SELECT 1 FROM zoi.listings WHERE id IN(listing,foreign_listing))OR EXISTS(SELECT 1 FROM zoi.workspaces WHERE id=other_ws)OR EXISTS(SELECT 1 FROM zoi.social_channels WHERE id=channel_id)OR EXISTS(SELECT 1 FROM auth.sessions WHERE id=ephemeral_session)OR EXISTS(SELECT 1 FROM zoi.editorial_sources WHERE id=fixture_source)OR EXISTS(SELECT 1 FROM zoi.social_posts WHERE meta->>'qa_publisher_fixture'='20261014')THEN RAISE EXCEPTION 'qa_publisher_fixture_collision';END IF;
 IF NOT EXISTS(SELECT 1 FROM zoi.workspaces w JOIN zoi.workspace_members m ON m.workspace_id=w.id JOIN zoi.user_profiles p ON p.id=m.profile_id JOIN auth.users u ON u.id=p.auth_user_id WHERE w.id=ws AND w.name='Zoi isolated QA 2026-09-30' AND w.owner_profile_id=actor AND m.profile_id=actor AND m.role='owner' AND p.auth_user_id=account AND u.email_confirmed_at IS NOT NULL AND u.deleted_at IS NULL AND NOT coalesce(u.is_anonymous,false)AND(u.banned_until IS NULL OR u.banned_until<=clock_timestamp()))THEN RAISE EXCEPTION 'dedicated_qa_authority_unavailable';END IF;
 SELECT s.id INTO sid FROM auth.sessions s WHERE s.user_id=account AND(s.not_after IS NULL OR s.not_after>clock_timestamp())ORDER BY s.created_at DESC NULLS LAST LIMIT 1;IF sid IS NULL THEN RAISE EXCEPTION 'dedicated_qa_current_session_unavailable';END IF;
 SELECT id INTO category FROM zoi.categories WHERE slug='restaurants'LIMIT 1;IF category IS NULL THEN RAISE EXCEPTION 'qa_category_unavailable';END IF;
 INSERT INTO zoi.workspaces(id,name,kind,owner_profile_id,created_by_auth)VALUES(other_ws,'Rollback-only publisher client workspace','business',actor,account);
 INSERT INTO zoi.listings(id,owner_workspace_id,entity_type,name,slug,primary_category_id,publish_status,moderation_status,marketplace_status,profile)VALUES(listing,ws,'business','Rollback-only publisher client','qa-publisher-owned-rollback-20261014',category,'draft','clean','hidden','{}'),(foreign_listing,other_ws,'business','Rollback-only foreign publisher client','qa-publisher-foreign-rollback-20261014',category,'draft','clean','hidden','{}');

 IF to_regprocedure('public.social_delivery_attempt_claim(uuid,bigint,uuid,integer)')IS NULL OR has_function_privilege('service_role','public.social_due_posts_current(integer)','EXECUTE')OR has_function_privilege('service_role','public.social_post_finalize(uuid,text)','EXECUTE')THEN RAISE EXCEPTION 'reviewed_publisher_schema_not_ready';END IF;
 INSERT INTO zoi.social_channels(id,workspace_id,platform,connected,status,access_token,external_id,token_expires_at,meta)VALUES(channel_id,ws,'facebook',true,'connected','rollback-fixture-not-a-provider-credential','qa-no-provider-destination',clock_timestamp()+interval'1 hour','{"qa_fixture":true}');
 INSERT INTO auth.sessions(id,user_id,created_at,updated_at,not_after)VALUES(ephemeral_session,account,clock_timestamp(),clock_timestamp(),clock_timestamp()-interval'1 minute');
 original_meta:=jsonb_build_object('qa_publisher_fixture','20261014','client_listing_id',listing,'campaign','Rollback-only publisher');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',account,'role','authenticated','session_id',sid)::text,true);PERFORM set_config('request.jwt.claim.sub',account::text,true);PERFORM set_config('request.jwt.claim.role','authenticated',true);EXECUTE 'SET LOCAL ROLE authenticated';
 post:=public.social_save_post(ws,'Rollback-only publisher no-send20261014',ARRAY[channel_id::text],clock_timestamp()-interval'1 minute','scheduled','[]',NULL,original_meta,NULL);
 PERFORM pg_temp.qa_publisher_assert(post.id IS NOT NULL AND post.author_profile=actor AND post.status='scheduled'AND post.published_at IS NULL,'actual_authorized_canonical_schedule_no_publication');
 EXECUTE format('SET LOCAL ROLE %I',executor);PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claim.role','service_role',true);EXECUTE 'SET LOCAL ROLE service_role';
 attempt:=public.social_delivery_attempt_claim(post.id,channel_id,'c1eb6d31-5454-4c5c-b52b-cd2610140010');
 PERFORM pg_temp.qa_publisher_assert(attempt->>'claimed'='true'AND attempt#>>'{payload,meta,client_listing_id}'=listing::text AND NOT(attempt::text LIKE '%rollback-fixture-not-a-provider-credential%'),'actual_scoped_preparation_no_credentials_persisted');
 replay:=public.social_delivery_attempt_claim(post.id,channel_id,'c1eb6d31-5454-4c5c-b52b-cd2610140010');
 PERFORM pg_temp.qa_publisher_assert(replay#>>'{attempt,id}'=attempt#>>'{attempt,id}'AND replay->>'lease'=attempt->>'lease','same_nonce_same_reservation');
 EXECUTE format('SET LOCAL ROLE %I',executor);UPDATE zoi.social_channels SET connected=false WHERE id=channel_id;EXECUTE 'SET LOCAL ROLE service_role';
 denied:=false;BEGIN PERFORM public.social_delivery_attempt_begin((attempt#>>'{attempt,id}')::uuid,(attempt->>'lease')::uuid);EXCEPTION WHEN raise_exception THEN denied:=SQLERRM='social_channel_not_publishable';END;PERFORM pg_temp.qa_publisher_assert(denied,'disconnected_channel_refuses_permission');
 EXECUTE format('SET LOCAL ROLE %I',executor);UPDATE zoi.social_channels SET connected=true WHERE id=channel_id;UPDATE zoi.listings SET owner_workspace_id=other_ws WHERE id=listing;EXECUTE 'SET LOCAL ROLE service_role';
 denied:=false;BEGIN PERFORM public.social_delivery_attempt_begin((attempt#>>'{attempt,id}')::uuid,(attempt->>'lease')::uuid);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;PERFORM pg_temp.qa_publisher_assert(denied,'revoked_client_refuses_permission');
 EXECUTE format('SET LOCAL ROLE %I',executor);UPDATE zoi.listings SET owner_workspace_id=ws WHERE id=listing;UPDATE zoi.workspace_members SET role='viewer'WHERE workspace_id=ws AND profile_id=actor;EXECUTE 'SET LOCAL ROLE service_role';
 denied:=false;BEGIN PERFORM public.social_delivery_attempt_begin((attempt#>>'{attempt,id}')::uuid,(attempt->>'lease')::uuid);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;PERFORM pg_temp.qa_publisher_assert(denied,'revoked_author_refuses_permission');
 EXECUTE format('SET LOCAL ROLE %I',executor);UPDATE zoi.workspace_members SET role='owner'WHERE workspace_id=ws AND profile_id=actor;EXECUTE 'SET LOCAL ROLE service_role';
 -- Permission only: deliberately do not call any provider or worker endpoint.
 permit:=public.social_delivery_attempt_begin((attempt#>>'{attempt,id}')::uuid,(attempt->>'lease')::uuid);
 PERFORM pg_temp.qa_publisher_assert(permit->>'dispatch'='true'AND permit#>>'{channel,id}'=channel_id::text,'actual_current_permission_no_network_call');
 replay:=public.social_delivery_attempt_begin((attempt#>>'{attempt,id}')::uuid,(attempt->>'lease')::uuid);PERFORM pg_temp.qa_publisher_assert(replay->>'dispatch'='false','dispatch_permission_not_reissued');
 EXECUTE format('SET LOCAL ROLE %I',executor);UPDATE zoi.social_post_targets SET delivery_lease_until=clock_timestamp()-interval'1 second'WHERE id=(attempt#>>'{attempt,id}')::uuid;UPDATE zoi.social_posts SET status='failed'WHERE id=post.id;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',account,'role','authenticated','session_id',sid)::text,true);PERFORM set_config('request.jwt.claim.sub',account::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 review:=public.social_delivery_attempts_get(ws,post.id);PERFORM pg_temp.qa_publisher_assert(review#>>'{attempts,0,state}'='unknown'AND NOT(review::text LIKE '%rollback-fixture-not-a-provider-credential%')AND NOT((review#>'{attempts,0}')?'lease'),'current_owner_unknown_read_no_service_capability');
 receipt:=public.social_delivery_reconcile(ws,(attempt#>>'{attempt,id}')::uuid,'c1eb6d31-5454-4c5c-b52b-cd2610140011','close_without_retry','{}');PERFORM pg_temp.qa_publisher_assert(receipt#>>'{attempt,state}'='closed','explicit_owner_closure_persisted');
 replay:=public.social_delivery_reconcile(ws,(attempt#>>'{attempt,id}')::uuid,'c1eb6d31-5454-4c5c-b52b-cd2610140011','close_without_retry','{}');PERFORM pg_temp.qa_publisher_assert(replay->>'replayed'='true','closure_exact_nonce_recovery');
 EXECUTE format('SET LOCAL ROLE %I',executor);UPDATE zoi.social_posts SET status='scheduled'WHERE id=post.id;PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);PERFORM set_config('request.jwt.claim.sub','',true);EXECUTE 'SET LOCAL ROLE service_role';
 receipt:=public.social_delivery_attempt_record((attempt#>>'{attempt,id}')::uuid,(attempt->>'lease')::uuid,'{"outcome":"rejected","error_code":"rollback_known_no_provider_call"}');PERFORM pg_temp.qa_publisher_assert(receipt#>>'{attempt,state}'='closed','late_fact_preserves_owner_closure');
 receipt:=public.social_delivery_attempt_claim(post.id,channel_id,'c1eb6d31-5454-4c5c-b52b-cd2610140012');PERFORM pg_temp.qa_publisher_assert(receipt->>'reason'='reconciliation_required','closed_attempt_never_blind_retries');
 denied:=false;BEGIN PERFORM public.social_delivery_attempts_finalize(post.id,attempt#>>'{attempt,payload_hash}','published');EXCEPTION WHEN raise_exception THEN denied:=SQLERRM='delivery_receipts_incomplete';END;PERFORM pg_temp.qa_publisher_assert(denied,'no_published_status_without_real_success_receipts');
 EXECUTE format('SET LOCAL ROLE %I',executor);
 PERFORM pg_temp.qa_publisher_assert(NOT EXISTS(SELECT 1 FROM zoi.community_post_deliveries d JOIN zoi.social_posts p ON p.id=d.social_post_id WHERE p.meta->>'qa_publisher_fixture'='20261014')AND NOT EXISTS(SELECT 1 FROM zoi.feed_posts WHERE body='Rollback-only publisher no-send20261014'),'no_public_feed_or_delivery');
END $qa$;
SELECT label,passed FROM qa_publisher_results ORDER BY label;
ROLLBACK;
SELECT jsonb_build_object('rollback_completed',true,'fixture_posts_absent',NOT EXISTS(SELECT 1 FROM zoi.social_posts WHERE meta->>'qa_publisher_fixture'='20261014'),'fixture_targets_absent',NOT EXISTS(SELECT 1 FROM zoi.social_post_targets WHERE delivery_request='c1eb6d31-5454-4c5c-b52b-cd2610140010'),'fixture_channels_absent',NOT EXISTS(SELECT 1 FROM zoi.social_channels WHERE id=-9126101400001),'fixture_source_absent',NOT EXISTS(SELECT 1 FROM zoi.editorial_sources WHERE id='qa-publisher-aged-rollback-20261014'),'fixture_links_absent',NOT EXISTS(SELECT 1 FROM zoi.editorial_draft_links WHERE source_id='qa-publisher-aged-rollback-20261014'),'fixture_session_absent',NOT EXISTS(SELECT 1 FROM auth.sessions WHERE id='c1eb6d31-5454-4c5c-b52b-cd2610140004'),'fixture_listings_absent',NOT EXISTS(SELECT 1 FROM zoi.listings WHERE id IN('c1eb6d31-5454-4c5c-b52b-cd2610140001','c1eb6d31-5454-4c5c-b52b-cd2610140002')),'fixture_workspace_absent',NOT EXISTS(SELECT 1 FROM zoi.workspaces WHERE id='c1eb6d31-5454-4c5c-b52b-cd2610140003'),'provider_or_publication_acceptance',false)AS publisher_no_send_contract_evidence;
